INSERT INTO public.material_versions (id, material_id, version_no, title, content, created_at) VALUES ('8283a40d-cbef-50e0-a5b0-e290d10bb566', '20916000-d3b9-5add-9f15-a6175a966d5e', '1', 'N4模拟测试第2回·問題8阅读短文', 'みなさんは 買い物が 好きですか。わたしは かわいい 服が［496］、よく 友だちと 買い物に 行きます。でも、ときどき お店［497］困ることがあります。［498-a］店員のことです。お店の人は わたしが お店に 入ると、すぐに わたしの ところに 来ます。わたしは［498-b］あまり 好きではありません。もちろん、お店の人は やさしいし、わたしに 親切に たくさん 話します。［499］、いろいろな服を 見せて くれます。でも、本当は、自分で ゆっくり 服を 見て、自分で 服を 選びたいです。いつも お店の人が わたしの 隣に いますから、ゆっくり 見ることが できません。本当に［500］。', '2026-09-03 08:18:22.026936+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.material_versions (id, material_id, version_no, title, content, created_at) VALUES ('67b2c32b-88a9-53e2-aaff-872ce47a2b99', '399b554e-0f53-5a76-a1dc-e34ceeb79102', '1', 'N5·第7单元·实战训练·問題3阅读短文', 'A「今度の日曜日、一緒に高尾山へ行きませんか。あそこの風景はきれいで［22］。」
INSERT INTO public.material_versions (id, material_id, version_no, title, content, created_at) VALUES ('29a38af8-8241-5fa3-a0a5-04e4546c52be', '4fd1978c-c9c3-56aa-b4ff-5698170eaf2a', '1', 'N5·第1单元·实战训练·問題3阅读短文', '昔、［22］はスーパー［23］でした。公園［24］。
INSERT INTO public.material_versions (id, material_id, version_no, title, content, created_at) VALUES ('25bf7d47-2e86-5b79-9638-8b7994ecbf4d', '73543c05-f81a-5190-b79b-19fa98319fe3', '1', 'N4·第10单元·实战训练·問題3阅读短文', '寒中お見舞い［21］。大変ご無沙汰しております。皆様お変わりが［22］か。今はインフルエンザにかかったから、自宅で休養して［23］。病気が治るまで、ずっと休む［24］です。寒さ厳しき折、お体にはお気をつけて［25］。', '2026-09-03 08:18:21.749146+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.material_versions (id, material_id, version_no, title, content, created_at) VALUES ('15a0eb53-8f1f-5fd9-9645-fe199e8675bd', '81702a2b-2a7a-557d-a410-b0e76b47f8d1', '1', 'N4·第9单元·实战训练·問題3阅读短文', '先日は楽しい旅行のお話をお聞かせいただいて、ありがとう［21］。実は今、わたしも旅行先で手紙を書いています。先週からずっと［22］と思っていた秋の京都に来てしまいました。先生がおいしい［23］お土産の紅葉焼きを買いました［24］、早速お送りしました。どうぞ召し上がって［25］。この手紙が届く頃には、もう東京に戻っていると思いますので、先生のお宅にお伺いしたいと思います。', '2026-09-03 08:18:21.749146+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.material_versions (id, material_id, version_no, title, content, created_at) VALUES ('c7a34f3a-bc06-539b-b5a2-f9ac01afdd6a', '88452e8f-14bf-5551-bc90-8d4a26fdd65e', '1', 'N5·第9单元·实战训练·問題3阅读短文', 'A「お昼ご飯は［22］。」
INSERT INTO public.material_versions (id, material_id, version_no, title, content, created_at) VALUES ('73fb750b-8316-53a7-8a27-60c055e73255', '88780a4c-a5cb-568b-bdc1-c5745111311f', '1', 'N4·第1单元·实战训练·問題3阅读短文', 'クラスメートの神田さんがずっと京都へ行き［21］。卒業旅行の目的地が京都だと聞いた時、彼女はとてもうれし［22］でした。京都に着いた神田さんはまず金閣寺を［23］に行きました。はじめ［24］金閣寺を見た神田さんが［25］ように喜んでいました。', '2026-09-03 08:18:21.749146+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.material_versions (id, material_id, version_no, title, content, created_at) VALUES ('cdfee100-55ac-5dcd-80ec-feb021672a99', '8b82b14a-644b-5a8a-9122-28d051aed3f6', '1', 'N5·第2单元·实战训练·問題3阅读短文', 'わたしは今、自分でご飯を［22］。
INSERT INTO public.material_versions (id, material_id, version_no, title, content, created_at) VALUES ('9a9d8a08-9759-4b8d-9975-1844aaed1318', '94a2c13a-2bbf-4e9b-a8b4-5c763926bc0f', '1', '図書館のお知らせ', E'【図書館からのお知らせ】\\n当館の開館時間は午前九時から午後六時までです。\\n土曜日と日曜日は午後五時まで、月曜日は休館日です。\\n本の貸出は一人三冊まで、期間は二週間です。\\nコピーは一枚十円です。', '2026-09-02 00:03:37.89064+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.material_versions (id, material_id, version_no, title, content, created_at) VALUES ('a5ba1b91-2aa6-5194-9546-88ecfe05c764', 'a4dcc38d-2e00-5953-88c4-0b4c008b1c8d', '1', 'N5·第6单元·实战训练·問題3阅读短文', '休みの日はいつも家で［22］。
INSERT INTO public.material_versions (id, material_id, version_no, title, content, created_at) VALUES ('8e601602-6445-5c8d-863c-b03405d16bbc', 'b75b44d9-0d1f-5215-8f7b-2ffd0f5c987e', '1', 'N4·第8单元·实战训练·問題3阅读短文', '世界一物価が高いと言われている東京で留学生活を［21］と思ったら、節約することが必要だ。アルバイト［22］で生活することは実際には不可能だと考えてください。その上、最近の不景気の影響で、アルバイト先を見つけることがますます難しくなっている。家賃を節約する［23］、友人同士などで一部屋を借りて共同生活することが［24］あいだに広まっている。留学生［25］、日本人も他人と生活することに嫌な感じがなくなっているようだ。', '2026-09-03 08:18:21.749146+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.material_versions (id, material_id, version_no, title, content, created_at) VALUES ('f8677e1f-b3f7-5832-9c00-6bc612f0773b', 'bf71bb09-8ab4-5918-9147-87364f32e94c', '1', 'N4·第4单元·实战训练·問題3阅读短文', '12月31日は大晦日ともいいます。除夜の鐘を［21］ながら、年越しそばを食べます。幸せがそばのように長く続く［22］と祈ります。昔は、前日［23］お正月の準備を終えなければなりません。みんなで門松を家の入り口に［24-a］、部屋の掃除を［24-b］します。そして、大晦日の夜も［25］ず、新年を迎えます。
INSERT INTO public.material_versions (id, material_id, version_no, title, content, created_at) VALUES ('df3f55cd-7919-595b-bde9-93a1b9e294c9', 'c388b938-b10a-50c9-956e-f4d88459ff8d', '1', 'N4·第6单元·实战训练·問題3阅读短文', 'メーカーが売り残ったり傷ついたりした製品を、安い値段で売る［21］作った店を「アウトレット店」［22］。「アウトレット」というのは、もともと米国で始まったシステムですが、だんだん世界に広がる［23］。日本では、衣類や食器［24］、日用品、スポーツ用品など、いろいろなメーカーのアウトレット店がここ数年のあいだに、できて［25］。', '2026-09-03 08:18:21.749146+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.material_versions (id, material_id, version_no, title, content, created_at) VALUES ('fcbdc9e3-33f2-4171-949c-c8e1edfeeb9f', 'cb92f0ee-2ef4-45aa-aca1-dc06af7068ed', '1', '図書館のお知らせ', E'【図書館からのお知らせ】\\n当館の開館時間は午前九時から午後六時までです。\\n土曜日と日曜日は午後五時まで、月曜日は休館日です。\\n本の貸出は一人三冊まで、期間は二週間です。\\nコピーは一枚十円です。', '2026-09-02 00:03:37.89064+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.material_versions (id, material_id, version_no, title, content, created_at) VALUES ('dd83331e-d3aa-5faf-af21-cbb1dae956af', 'ceb334b0-b6b8-5f22-9bb0-589b6d27b315', '1', 'N5·第8单元·实战训练·問題3阅读短文', '先週の土曜日、友達と一緒に海辺へ行きました。海が［22］。
INSERT INTO public.material_versions (id, material_id, version_no, title, content, created_at) VALUES ('7bc66d81-8006-5501-9b83-65d2e15fdb3c', 'd6aa210d-2d4c-5020-8db1-75619ee50ed2', '1', 'N5·第10单元·实战训练·問題3阅读短文', 'A「田中さん、おはようございます。」
INSERT INTO public.material_versions (id, material_id, version_no, title, content, created_at) VALUES ('eb908acd-4377-58f4-b73f-01431489415d', 'db0bb10a-bed3-54a0-9ef6-591978853ad1', '1', 'N4·第7单元·实战训练·問題3阅读短文', '柔道の特長は「柔能く剛を制す」と言われている。これは弱いものでも強いものに勝つ［21］という意味です。つまり、相手の力を上手に利用すれ［22］、強い相手でも倒す［23］のだ。調査［24］、現在世界の柔道人口は600万人を超えたそうです。柔道を練習する人達は帯の色でその人の実力を推測することが［25］。', '2026-09-03 08:18:21.749146+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.material_versions (id, material_id, version_no, title, content, created_at) VALUES ('8d77f487-dfea-57ce-a54b-13104a299578', 'e12c3d51-ad3f-5fa5-b91c-c101ec06c897', '1', 'N4模拟测试第1回·問題8阅读短文', 'マリアさんの じこしょうかい
INSERT INTO public.material_versions (id, material_id, version_no, title, content, created_at) VALUES ('898b3104-55b9-536f-b0a0-cf8f378eedb0', 'e181c8b9-e451-536b-a82a-9f562e4cf72a', '1', 'N4·第5单元·实战训练·問題3阅读短文', '3月3日は日本の雛祭り（注）です。その日に女の子［21］いる家に人形を飾ります。その人形は女の子が元気に成長する［22］という願いが込められています。普通の人形は四段［23］ありますが、最近は七、八段［24］あるものが売り出されています。しかし最近はこれを飾らない家の［25］多くなりました。
INSERT INTO public.material_versions (id, material_id, version_no, title, content, created_at) VALUES ('33b7b702-ad5f-5929-8c07-56c73aeb89aa', 'e437dd7b-53d1-5820-87de-0228908af719', '1', 'N5模拟测试第2回·問題7阅读短文', '（1）マイケルさんの じこしょうかい
