INSERT INTO public.material_versions (id, material_id, version_no, title, content, created_at) VALUES ('d2122352-c4e3-5c0a-a757-22447dd13922', 'f5d13999-a1e9-5813-a832-27d3e76cdc49', '1', 'N4·第3单元·实战训练·問題3阅读短文', '今日は友達と博物館へ行きました。ガイドさんの話では、写真を撮っても［21］が、手で［22］。午後3時に母から電話がかかってきました。まだ［23］んですが、もう［24］なりません。写真をいっぱい撮りましたから、うれしかったです。今日のことはきっと［25］思い出になります。', '2026-09-03 08:18:21.749146+08') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.material_versions (id, material_id, version_no, title, content, created_at) VALUES ('03eca620-2288-55a2-b2eb-85c9318fc85b', 'fd087699-ba21-5a57-9936-e19beb329bee', '1', 'N5·第3单元·实战训练·問題3阅读短文', 'A「昨日、友達と一緒に映画を［22］に行きました。」
INSERT INTO public.material_versions (id, material_id, version_no, title, content, created_at) VALUES ('5cad15f8-6f82-56fc-9a8e-d9d913e16954', 'ff13c7ff-db72-52ab-8c73-9e8688b5bcfb', '1', 'N5·第5单元·实战训练·問題3阅读短文', 'A「週末、いつも［22］。」
INSERT INTO public.material_versions (id, material_id, version_no, title, content, created_at) VALUES ('3beeee0d-f3cd-5c97-bdaa-2ab2e196374c', 'ffd427b8-d1ff-5337-8303-0cc13a6e3cb7', '1', 'N4·第2单元·实战训练·問題3阅读短文', '今日は友達と一緒に遊園地に行きました。人がたくさん並んで［21］が、みんな静かでした。遊園地に入った後、友達に［22］ジェットコースターまで乗りました。最初は怖くて乗りたくなかったんですが、結局乗って［23］。実はそんなに怖くなかった［24］。私たちは夜8時までずっと遊んでいました。家に帰った後、自分がジェットコースターに乗った［25］を両親に話しました。', '2026-09-03 08:18:21.749146+08') ON CONFLICT (id) DO NOTHING;
