INSERT INTO public.question_version_knowledge_points (question_version_id, knowledge_point_id) VALUES ('ffc09aa2-054f-4831-95c8-7be936d0b01b', 'e8b91437-527a-52c6-9d86-6fe922651cfc') ON CONFLICT DO NOTHING;
INSERT INTO public.question_version_knowledge_points (question_version_id, knowledge_point_id) VALUES ('fffe7e37-b362-48d1-a155-96d579f05aec', '2d7157f8-afb7-58a0-85ea-b3d775f216a2') ON CONFLICT DO NOTHING;
INSERT INTO public.question_ai_explanations (question_version_id, prompt_version, model, explanation, created_at, updated_at) VALUES ('0177f162-920a-5376-9eb9-19fecc4b5be1', 'practice_batch_analysis.v1', 'deepseek-v4-flash', '答案C「こんな」正确。「( )悪い会社に入りたくない」的空格后是名词短语「悪い会社」，需要能修饰名词的词。「こんな」是连体词，意为“这样的”，带有评价、感叹的语气，正好表达“不想进这样的坏公司”。A「ここ」、B「これ」不能直接修饰名词；D「この」虽可修饰名词，但只表示“这个”，不能表达“这种、这般”的嫌弃语气，所以此处用「こんな」最自然。', '2026-09-03 11:33:43.277612+08', '2026-09-03 11:33:43.277612+08') ON CONFLICT (question_version_id) DO NOTHING;
INSERT INTO public.question_ai_explanations (question_version_id, prompt_version, model, explanation, created_at, updated_at) VALUES ('01e6d37b-9a3a-5a34-93ac-988c514100cb', 'practice_batch_analysis.v1', 'deepseek-v4-flash', '「ノート（笔记本）」是装订成册的书本类，用「冊」计数，如「ノート一冊」。答案应写“冊”。注意铅笔用「本」、纸用「枚」。', '2026-09-03 11:30:22.579731+08', '2026-09-03 11:30:22.579731+08') ON CONFLICT (question_version_id) DO NOTHING;
INSERT INTO public.question_ai_explanations (question_version_id, prompt_version, model, explanation, created_at, updated_at) VALUES ('050bb18e-18f5-431b-9073-8c6b51350c26', 'practice_batch_analysis.v1', 'deepseek-v4-flash', '「ノート」是笔记本，装订成册的物品用助数词「冊」来数，如「一冊、二冊」。「冊」也用于书籍、杂志等。「枚」用于一张一张的纸，但笔记本是整体装订本，所以不用「枚」；「本」细长物、「台」机器也不适用。此题考查对“书本类”量词的记忆，应填「冊」。', '2026-09-03 15:47:34.250068+08', '2026-09-03 15:47:34.250068+08') ON CONFLICT (question_version_id) DO NOTHING;
INSERT INTO public.question_ai_explanations (question_version_id, prompt_version, model, explanation, created_at, updated_at) VALUES ('08432493-c46a-4253-84b1-25a0c55e7480', 'practice_batch_analysis.v1', 'deepseek-v4-flash', '结论：选D“この”。“会社”是名词，空处需要能修饰名词的连体词，因此选“この”。“この会社”意为“这家公司”。A“ここ”、B“これ”不能直接修饰名词；C“こんな”虽能修饰名词，但表示“这样的公司”，与后面询问“どんな会社ですか”这一对具体公司性质的提问不搭配。此题关键是看到空后名词，优先考虑修饰名词的连体词“この/その/あの”。', '2026-09-03 14:37:50.530704+08', '2026-09-03 14:37:50.530704+08') ON CONFLICT (question_version_id) DO NOTHING;
INSERT INTO public.question_ai_explanations (question_version_id, prompt_version, model, explanation, created_at, updated_at) VALUES ('0e5797c0-5246-54b1-97f6-276576a85584', 'practice_batch_analysis.v1', 'deepseek-v4-flash', '前半句是“那个房间是王先生的”，与小李形成对比，后半应说“不是小李的”。此处由「王さんのだ」可判断用名词否定，短句形式为「ではない」（B）。A「だ」是肯定；C「だった」是过去肯定；D「ではなかった」虽是过去否定，但句子无过去标志，且与前半句现在时态不匹配。', '2026-09-03 11:30:22.579731+08', '2026-09-03 11:30:22.579731+08') ON CONFLICT (question_version_id) DO NOTHING;
INSERT INTO public.question_ai_explanations (question_version_id, prompt_version, model, explanation, created_at, updated_at) VALUES ('0f3b7059-3a4a-5a85-bd4c-150d087bb1f4', 'practice_batch_analysis.v1', 'deepseek-v4-flash', '“赤く”是形容词“赤い（あかい）”的连用形，句意“苹果变红了”，故选 d。干扰项读音对应：ふとく＝太く，ひくく＝低く，ふるく＝古く。需要注意“赤い”在修饰“なる”时要把词尾“い”变为“く”，读作“あかく”，而不是按外形直接读成“あかい”。', '2026-09-03 11:30:59.421043+08', '2026-09-03 11:30:59.421043+08') ON CONFLICT (question_version_id) DO NOTHING;
INSERT INTO public.question_ai_explanations (question_version_id, prompt_version, model, explanation, created_at, updated_at) VALUES ('11c365b5-5564-5ae3-9da4-f118774fdd00', 'practice_batch_analysis.v1', 'deepseek-v4-flash', '「手紙（信）」用「通」计数，如「手紙一通」。答案应写“通”。信件、电子邮件等多用「通」。', '2026-09-03 11:30:22.579731+08', '2026-09-03 11:30:22.579731+08') ON CONFLICT (question_version_id) DO NOTHING;
INSERT INTO public.question_ai_explanations (question_version_id, prompt_version, model, explanation, created_at, updated_at) VALUES ('169c4e45-0ecf-47bf-b7e9-4356baf0eeb5', 'practice_batch_analysis.v1', 'deepseek-v4-flash', '题干“あそこに立っている人は( )ですか”问的是“站在那里的人是谁”，指人的身份，所以用疑问词「だれ」。“どこ”问地点；“どれ”用于从几个事物中选择哪一个，通常不直接用于人；“どんな”问“什么样的”，若想问那个人是什么样的人可以说「どんな人ですか」，但句子问的是“是谁”而非“什么样”，故正确答案是「だれ」。', '2026-09-03 15:47:34.250068+08', '2026-09-03 15:47:34.250068+08') ON CONFLICT (question_version_id) DO NOTHING;
INSERT INTO public.question_ai_explanations (question_version_id, prompt_version, model, explanation, created_at, updated_at) VALUES ('18f01a30-49e6-5c24-8fcf-3fc808506217', 'practice_batch_analysis.v1', 'deepseek-v4-flash', '题干为“站在那里的那个人是谁”，谓语「ですか」前的部分需回答“哪个人”，且人は已经给出人的名词，不需要再用「だれ」修饰，但在本句结构「あそこに立っている人は（ ）ですか」中要填能接在“人は”后的疑问词，指代“谁”。由于主语是「人」，选项中只有「だれ（C）」表示“谁”。A「どこ」问地点；B「どれ」只能在若干物品中选一个，不用于已知实体“人”；D「どんな」意为“什么样的”，应修饰名词，不能直接作这里的表语。', '2026-09-03 11:30:22.579731+08', '2026-09-03 11:30:22.579731+08') ON CONFLICT (question_version_id) DO NOTHING;
INSERT INTO public.question_ai_explanations (question_version_id, prompt_version, model, explanation, created_at, updated_at) VALUES ('1acd98a9-7232-530e-978d-368ed62e05a2', 'practice_batch_analysis.v1', 'deepseek-v4-flash', '题干为“林先生不是日本人，是中国人”，表示“不是”的现在肯定否定判断是「ではありません」（C）。A「です」与后半矛盾；B「でした」为过去肯定；D「ではありませんでした」为过去否定，与后句“中国人です”的现在时态不匹配。', '2026-09-03 11:30:22.579731+08', '2026-09-03 11:30:22.579731+08') ON CONFLICT (question_version_id) DO NOTHING;
INSERT INTO public.question_ai_explanations (question_version_id, prompt_version, model, explanation, created_at, updated_at) VALUES ('205fdab9-4d12-5bf6-9c46-68a6fad3b70a', 'practice_batch_analysis.v1', 'deepseek-v4-flash', '本题考汉字“会”的读音。句中“会いました”对应动词“会う（あう）”，表示“见面、遇见”，所以读作“あいました”。其他选项：かいました对应“買いました”，すいました对应“吸いました”，いいました对应“言いました”，意思都与“见到田中先生”不符。常见误区是把“会”读成音读“かい”，但“会う”是训读，写作“会”读作“あ”。', '2026-09-03 11:30:59.421043+08', '2026-09-03 11:30:59.421043+08') ON CONFLICT (question_version_id) DO NOTHING;
INSERT INTO public.question_ai_explanations (question_version_id, prompt_version, model, explanation, created_at, updated_at) VALUES ('2e2e02d2-1c83-5456-87a9-f663da9ca81e', 'practice_batch_analysis.v1', 'deepseek-v4-flash', '「パソコン（电脑）」属于机械、设备、车辆等，用「台」计数，如「パソコン一台」。答案应写“台”。', '2026-09-03 11:30:22.579731+08', '2026-09-03 11:30:22.579731+08') ON CONFLICT (question_version_id) DO NOTHING;
INSERT INTO public.question_ai_explanations (question_version_id, prompt_version, model, explanation, created_at, updated_at) VALUES ('2fd5719b-76be-5cfc-9797-55c31885896f', 'practice_batch_analysis.v1', 'deepseek-v4-flash', '「ウサギ（兔子）」作为动物，一般用「匹」计数；但在日语中，兔子传统上也有用「羽」计数的情况，本题官方答案为「羽」。按教材要求应写“羽”。一般小型动物多用「匹」（猫、狗等），鸡、鸭等鸟类用「羽」。', '2026-09-03 11:30:22.579731+08', '2026-09-03 11:30:22.579731+08') ON CONFLICT (question_version_id) DO NOTHING;
INSERT INTO public.question_ai_explanations (question_version_id, prompt_version, model, explanation, created_at, updated_at) VALUES ('3056dc57-df1e-5530-af9c-29075bd5602e', 'practice_batch_analysis.v1', 'deepseek-v4-flash', '这是名词谓语句「学生」的变形练习，本题未作答。敬体现在时肯定「学生です」、否定「学生ではありません」；敬体过去时肯定「学生でした」、否定「学生ではありませんでした」。简体现在时肯定「学生だ」、否定「学生ではない」；简体过去时肯定「学生だった」、否定「学生ではなかった」。口语中否定也可用「じゃ」。敬体句末用です/でした，简体句末用だ/だった；否定用では（じゃ）＋ない/なかった。', '2026-09-03 11:33:43.277612+08', '2026-09-03 11:33:43.277612+08') ON CONFLICT (question_version_id) DO NOTHING;
INSERT INTO public.question_ai_explanations (question_version_id, prompt_version, model, explanation, created_at, updated_at) VALUES ('3b20993c-be6c-5167-9dfe-9914646c1efd', 'practice_batch_analysis.v1', 'deepseek-v4-flash', '“今朝”在日语中训读为“けさ”，意思是“今天早上”，故选 b。干扰项中“きさ”不是标准读音；“あさ”是“朝”，“いま”是“今”。句意“今朝7时起床”。常见误区是把“今”和“朝”按各自常用音拼成“いまあさ”，但“今朝”是固定特殊读音，需要整体记忆为“けさ”。', '2026-09-03 11:30:59.421043+08', '2026-09-03 11:30:59.421043+08') ON CONFLICT (question_version_id) DO NOTHING;
INSERT INTO public.question_ai_explanations (question_version_id, prompt_version, model, explanation, created_at, updated_at) VALUES ('46effbad-7b4c-4aba-a183-f654f1d416ad', 'practice_batch_analysis.v1', 'deepseek-v4-flash', '结论：选A“ここ”。句子表示“这里是我们的公司”，“会社”是一个场所，因此用地点代词“ここ”作主语。B“これ”指事物，不表示地点；C“こんな”、D“この”都是连体词，不能直接接“は”，其中“この”后面必须接“会社”等名词。掌握“ここ/そこ/あそこ/どこ”表示地点，而“これ/それ/あれ/どれ”表示事物，可避免此类误选。', '2026-09-03 14:37:50.530704+08', '2026-09-03 14:37:50.530704+08') ON CONFLICT (question_version_id) DO NOTHING;
INSERT INTO public.question_ai_explanations (question_version_id, prompt_version, model, explanation, created_at, updated_at) VALUES ('4d7a5684-f488-5860-982e-1388b6c12aa9', 'practice_batch_analysis.v1', 'deepseek-v4-flash', '「スニーカー（运动鞋）」按“双”计数，用「足」，如「スニーカー一足」。答案应写“足”。鞋、袜子都用「足」；注意与“脚”的「足」字相同，但此处是量词。', '2026-09-03 11:30:22.579731+08', '2026-09-03 11:30:22.579731+08') ON CONFLICT (question_version_id) DO NOTHING;
INSERT INTO public.question_ai_explanations (question_version_id, prompt_version, model, explanation, created_at, updated_at) VALUES ('54271f7e-fb14-51da-93ca-b46773732429', 'practice_batch_analysis.v1', 'deepseek-v4-flash', '答案应为B「それ」。「( )は彼女の作品ではありません」中空格后是「は」，需要能单独作主语的指示代词，指代前面提到过的事物。B「それ」意为“那个东西、那件作品”，可作主语。A「その」是连体词，不能单独使用；D「そんな」也是连体词，不能作主语；C「そちら」虽可作主语，但多指方向、地点或对方处所，不适合指作品。注意：それ接は构成“那是……”，而不是その＋名词。', '2026-09-03 11:33:43.277612+08', '2026-09-03 11:33:43.277612+08') ON CONFLICT (question_version_id) DO NOTHING;
INSERT INTO public.question_ai_explanations (question_version_id, prompt_version, model, explanation, created_at, updated_at) VALUES ('56897480-15ff-529e-971b-15d5c4db8ab3', 'practice_batch_analysis.v1', 'deepseek-v4-flash', '题干为“当学生的时候，去了很多地方”。「とき」前接名词修饰时，名词的过去肯定形式为「だった」，构成「学生だったとき」（A）。B「でした」是敬体过去，不能直接修饰「とき」；C「だ」是现在肯定简体；D「です」是现在敬体，无法表示“当时是学生”的过去状态。', '2026-09-03 11:30:22.579731+08', '2026-09-03 11:30:22.579731+08') ON CONFLICT (question_version_id) DO NOTHING;
INSERT INTO public.question_ai_explanations (question_version_id, prompt_version, model, explanation, created_at, updated_at) VALUES ('5cd568d3-6274-58b8-b468-a9690a4d11c8', 'practice_batch_analysis.v1', 'deepseek-v4-flash', '答案应为B「これ」。句子「( )はうちの会社の新製品です」中，空格后直接接「は」，需要能单独作主语的指示代词。「これ」指代“这个东西”，可作主语。D「この」是连体词，必须后续名词，不能直接接「は」；A「ここ」指地点；C「こんな」也是连体词，表示“这样的”，不能直接作主语。常见误区是看到近处事物就选「この」，却忽略其后没有名词时应选「これ」。', '2026-09-03 11:33:43.277612+08', '2026-09-03 11:33:43.277612+08') ON CONFLICT (question_version_id) DO NOTHING;
INSERT INTO public.question_ai_explanations (question_version_id, prompt_version, model, explanation, created_at, updated_at) VALUES ('63d5060b-0e7b-4460-b4dc-818d08f0b984', 'practice_batch_analysis.v1', 'deepseek-v4-flash', '结论：选C“こんな”。空后是“悪い会社”，需要能修饰名词的连体词。“こんな悪い会社”意为“像这样的坏公司”，表达说话人不想加入这类公司的态度。D“この”虽然也能修饰公司，但表示“这个特定的公司”，而不是“这种/这类”的含义；A“ここ”是地点代词，B“これ”是事物代词，都不能直接放在名词前。本题关键是区分“この（特定的这个）”和“こんな（这样的、这种）”。', '2026-09-03 14:37:50.530704+08', '2026-09-03 14:37:50.530704+08') ON CONFLICT (question_version_id) DO NOTHING;
INSERT INTO public.question_ai_explanations (question_version_id, prompt_version, model, explanation, created_at, updated_at) VALUES ('67789e1d-cc5d-418f-9466-41c523374423', 'practice_batch_analysis.v1', 'deepseek-v4-flash', '「写真」是照片，属于薄而平的物品，日语中用助数词「枚」计数，如「一枚、二枚」。「枚」也用于纸张、明信片、盘子、衬衫等扁平物。「本」用于细长物，「冊」用于书和笔记本，「台」用于机器，因此这里应填「枚」。在N5量词题中，“照片”与“纸”都优先联想起「枚」。', '2026-09-03 15:47:34.250068+08', '2026-09-03 15:47:34.250068+08') ON CONFLICT (question_version_id) DO NOTHING;
INSERT INTO public.question_ai_explanations (question_version_id, prompt_version, model, explanation, created_at, updated_at) VALUES ('68294856-ba63-5577-afae-cfa245b8f9f4', 'practice_batch_analysis.v1', 'deepseek-v4-flash', '「年齢（年龄）」用「歳」表示，如「二十歳」。答案应写“歳”。注意「何歳」询问年龄。', '2026-09-03 11:30:22.579731+08', '2026-09-03 11:30:22.579731+08') ON CONFLICT (question_version_id) DO NOTHING;
INSERT INTO public.question_ai_explanations (question_version_id, prompt_version, model, explanation, created_at, updated_at) VALUES ('688ef542-f1bc-5bab-b36f-bbefb1648353', 'practice_batch_analysis.v1', 'deepseek-v4-flash', '「写真（照片）」是薄而平的东西，用「枚」计数，如「写真一枚」。答案应写“枚”。纸张、邮票等也用「枚」。', '2026-09-03 11:30:22.579731+08', '2026-09-03 11:30:22.579731+08') ON CONFLICT (question_version_id) DO NOTHING;
INSERT INTO public.question_ai_explanations (question_version_id, prompt_version, model, explanation, created_at, updated_at) VALUES ('6f1f83f2-3f69-528c-bb4e-4ed8a427ee91', 'practice_batch_analysis.v1', 'deepseek-v4-flash', '答案应为C「そちら」。「( )までどのぐらいかかりますか」询问“到那里需要多长时间”，空格后接「まで」，要求能表示地点或方向的词。C「そちら」可表示“那边、您那边”，符合句意。D「そんな」是连体词，后面必须接名词，不能接「まで」；A「その」也是连体词，需接名词；B「それ」指事物，不用于表示“到某处”。同类例句：「そちらまで歩いて行きます。」', '2026-09-03 11:33:43.277612+08', '2026-09-03 11:33:43.277612+08') ON CONFLICT (question_version_id) DO NOTHING;
INSERT INTO public.question_ai_explanations (question_version_id, prompt_version, model, explanation, created_at, updated_at) VALUES ('7683e758-d9d9-531f-a23d-a87fead7c3b3', 'practice_batch_analysis.v1', 'deepseek-v4-flash', '答案应为A「その」。「( )電子辞書は先生のです」中空格后是名词「電子辞書」，需要用连体词修饰。A「その」＋「電子辞書」＝“那台电子辞典”，符合句意。C「そちら」多表示方向、地点或“您那边”，不能直接后续名词；B「それ」是代词，不能接名词；D「そんな」虽可接名词，但意为“那样的”，与后文“是老师的”这一具体所属搭配不自然。选择时先看空格后有无名词：有名词优先考虑この/その/あの、こんな/そんな。', '2026-09-03 11:33:43.277612+08', '2026-09-03 11:33:43.277612+08') ON CONFLICT (question_version_id) DO NOTHING;
INSERT INTO public.question_ai_explanations (question_version_id, prompt_version, model, explanation, created_at, updated_at) VALUES ('83678e57-b0d4-5e2c-ba0c-bb07474e0a53', 'practice_batch_analysis.v1', 'deepseek-v4-flash', '答案应为A「ここ」。「( )はうちの会社です」表示“（这个地方）是我们公司”，「は」前需要能独立作主语的地点指示词。A「ここ」意为“这里”，符合句意。B「これ」指物，不用于公司所在地；C「こんな」是“这样的”，是连体词，不能指地点，也不能直接接「は」；D「この」也是连体词，后面必须接名词。若想说“这样的公司”，应说「こんな会社です」，而不是「こんなは…」。', '2026-09-03 11:33:43.277612+08', '2026-09-03 11:33:43.277612+08') ON CONFLICT (question_version_id) DO NOTHING;
INSERT INTO public.question_ai_explanations (question_version_id, prompt_version, model, explanation, created_at, updated_at) VALUES ('849ceaa1-9732-5881-9134-d59a57307590', 'practice_batch_analysis.v1', 'deepseek-v4-flash', '量词搭配题。万年筆（钢笔）细长，用「本」计数。数细长物时用「〜本」，如「鉛筆一本」「ビール一本」。答案应写“本”。', '2026-09-03 11:30:22.579731+08', '2026-09-03 11:30:22.579731+08') ON CONFLICT (question_version_id) DO NOTHING;
INSERT INTO public.question_ai_explanations (question_version_id, prompt_version, model, explanation, created_at, updated_at) VALUES ('8868afa7-c21b-4f35-8a9a-b95b83e4c537', 'practice_batch_analysis.v1', 'deepseek-v4-flash', '结论：选B“それ”。句子结构是“（ ）は彼女の作品ではありません”，“は”前需要能独立作主语的体言。“それ”作为指示代词，可以指代某个东西/作品，符合“那不是她的作品”的句意。A“その”、D“そんな”是连体词，后面必须接名词；C“そちら”多指方向、地点或对方一方，不适合指代“作品”。常见误区是看到“那个”就选“その”，但没有后续名词时应选“それ”。', '2026-09-03 14:37:50.530704+08', '2026-09-03 14:37:50.530704+08') ON CONFLICT (question_version_id) DO NOTHING;
INSERT INTO public.question_ai_explanations (question_version_id, prompt_version, model, explanation, created_at, updated_at) VALUES ('909037c4-a890-4184-a5d9-756836b7e169', 'practice_batch_analysis.v1', 'deepseek-v4-flash', '结论：选C“そちら”。“まで”表示到达点、目的地，前接表示地点或方向的词。“そちら”有“那里、您那边”的意思，属于礼貌的地点/方向说法，因此“そちらまでどのぐらいかかりますか”意为“到那里要多长时间/多久”。A“その”是连体词，后面要接名词；B“それ”指事物，一般不作为地点词与“まで”搭配；D“そんな”是“那样的”，不能表示地点。', '2026-09-03 14:37:50.530704+08', '2026-09-03 14:37:50.530704+08') ON CONFLICT (question_version_id) DO NOTHING;
INSERT INTO public.question_ai_explanations (question_version_id, prompt_version, model, explanation, created_at, updated_at) VALUES ('95fd62a9-ccf7-5749-b407-6e327f325468', 'practice_batch_analysis.v1', 'deepseek-v4-flash', '题干为“您太太做什么工作”，句子为「奥さんは（ ）仕事をしていますか」，「どんな（D）」作连体词修饰后续名词「仕事」，意为“什么样的”。A「どこ」表示地点，不能直接修饰「仕事」；B「どれ」是疑问代词，作主语或宾语，不能放在名词前作修饰语；C「だれ」问人。注意「どんな＋名词」与「どれ」单独使用的位置不同。', '2026-09-03 11:30:22.579731+08', '2026-09-03 11:30:22.579731+08') ON CONFLICT (question_version_id) DO NOTHING;
INSERT INTO public.question_ai_explanations (question_version_id, prompt_version, model, explanation, created_at, updated_at) VALUES ('9e83e12d-5637-59ca-8248-3a48a29d97b1', 'practice_batch_analysis.v1', 'deepseek-v4-flash', '句意为“我住在这个（公寓）的6层”。能从“6階に住んでいます”自然搭配的是“アパート”（公寓），故选 d。其他外来语：クラス＝班级，レコード＝唱片，トイレ＝厕所。误区是把“トイレ”当成住宅类词选入，但句意是在某栋建筑里居住；“アパート”的“～の6階”表示建筑的第6层。', '2026-09-03 11:30:59.421043+08', '2026-09-03 11:30:59.421043+08') ON CONFLICT (question_version_id) DO NOTHING;
INSERT INTO public.question_ai_explanations (question_version_id, prompt_version, model, explanation, created_at, updated_at) VALUES ('a1a72662-594f-57b3-94fc-04d944c1ad62', 'practice_batch_analysis.v1', 'deepseek-v4-flash', '“鉛筆”的正确读音是“えんぴつ”，意为铅笔，故选 c。干扰项えんびつ把“ぴ”错读成浊音“び”；えいひつ、えいびつ则错加了长音。常见误区是受汉字“鉛”与中文影响读成“えい”，或受“ん”后面发音影响而浊化。日语中“鉛筆”应读“えんぴつ”，需要按惯用读音整体记忆。', '2026-09-03 11:30:59.421043+08', '2026-09-03 11:30:59.421043+08') ON CONFLICT (question_version_id) DO NOTHING;
INSERT INTO public.question_ai_explanations (question_version_id, prompt_version, model, explanation, created_at, updated_at) VALUES ('a66ad824-3382-493c-ad15-b266db195b7b', 'practice_batch_analysis.v1', 'deepseek-v4-flash', '结论：按名词谓语句“学生です”在各语体、时态、肯否形式中变形填写。敬体现在时肯定为“学生です”，否定为“学生ではありません”；敬体过去时肯定为“学生でした”，否定为“学生ではありませんでした”。简体现在时肯定为“学生だ”，否定为“学生ではない”；简体过去时肯定为“学生だった”，否定为“学生ではなかった”。口语中“ではありません/ではない”也常说成“じゃありません/じゃない”。注意敬体否定要整体变化，不要把“です”和“ありません”重复叠加。', '2026-09-03 14:37:50.530704+08', '2026-09-03 14:37:50.530704+08') ON CONFLICT (question_version_id) DO NOTHING;
INSERT INTO public.question_ai_explanations (question_version_id, prompt_version, model, explanation, created_at, updated_at) VALUES ('a6ed9d59-733e-4174-8187-c5a226fb20d1', 'practice_batch_analysis.v1', 'deepseek-v4-flash', '结论：选A“その”。空后是“電子辞書”，是名词，需要用连体词来修饰，“その電子辞書”意为“那台电子词典”。B“それ”是代词，不能直接放在名词前修饰名词；C“そちら”通常指方向/地点/对方，不用于直接修饰物品；D“そんな”表示“那样的”，语义上不如“その”自然，且本句应指特定的那台词典。判断依据：空后是名词，优先选择可作定语的“この/その/あの”。', '2026-09-03 14:37:50.530704+08', '2026-09-03 14:37:50.530704+08') ON CONFLICT (question_version_id) DO NOTHING;
INSERT INTO public.question_ai_explanations (question_version_id, prompt_version, model, explanation, created_at, updated_at) VALUES ('a9ac2f14-54fc-4edd-b8ca-4eef9b72b130', 'practice_batch_analysis.v1', 'deepseek-v4-flash', '「パソコン」是电脑，电脑、汽车、冰箱、洗衣机等机械或电器用品一般用助数词「台」来数，如「一台、二台」。「冊」用于书、「枚」用于薄平物品、「本」用于细长物体，均不适用于电脑。本题需要记住表示“机器设备”的量词是「台」，所以应填「台」。', '2026-09-03 15:47:34.250068+08', '2026-09-03 15:47:34.250068+08') ON CONFLICT (question_version_id) DO NOTHING;
INSERT INTO public.question_ai_explanations (question_version_id, prompt_version, model, explanation, created_at, updated_at) VALUES ('ab013780-992c-5681-ac18-33d1a553cc1a', 'practice_batch_analysis.v1', 'deepseek-v4-flash', '句意为“在公园的（入口）见面了”。“入口”读作“いりぐち”，表进入某处的门口；搭配“公園の入口で”表示地点，故选 c。其他词义：でんとう＝电灯，はんぶん＝一半，ゆうはん＝晚饭。误区是“入口”容易和“出口（でぐち）”“入り口”的书写混淆，且“いりぐち”会发生浊化，不能读成“いりくち”。', '2026-09-03 11:30:59.421043+08', '2026-09-03 11:30:59.421043+08') ON CONFLICT (question_version_id) DO NOTHING;
INSERT INTO public.question_ai_explanations (question_version_id, prompt_version, model, explanation, created_at, updated_at) VALUES ('ac7acd95-3b27-52ed-800d-0447a73a47c3', 'practice_batch_analysis.v1', 'deepseek-v4-flash', '题干为“他的作品中，你最喜欢哪一个/哪部”，后接が，谓语为「一番好き」，问的是具体对象，因此用「どれ」（B）。A「どこ」问地点；C「だれ」问人；D「どんな」虽可表示“什么样的”，但放在该结构中是修饰名词，不能单独承担「が一番好きですか」的主语，应写成「どんな作品が一番好きですか」等。常见误区是把“哪一部作品”想成“什么样的作品”，从而选どんな。', '2026-09-03 11:30:22.579731+08', '2026-09-03 11:30:22.579731+08') ON CONFLICT (question_version_id) DO NOTHING;
INSERT INTO public.question_ai_explanations (question_version_id, prompt_version, model, explanation, created_at, updated_at) VALUES ('ad2b426b-d44b-4292-b3a5-27a1419a7cf3', 'practice_batch_analysis.v1', 'deepseek-v4-flash', '「年齢」表示年龄，日语中数年龄用助数词「歳」，如「20歳（はたち）」。常见误区是写作「才」，它作为“歳”的略字在日常生活中可见，但标准日语学习中通常写「歳」。本题是量词填空，考查“岁数”的量词，所以应填「歳」。同时注意「一歳、八歳、十歳、二十歳」等特殊读音也需留意。', '2026-09-03 15:47:34.250068+08', '2026-09-03 15:47:34.250068+08') ON CONFLICT (question_version_id) DO NOTHING;
INSERT INTO public.question_ai_explanations (question_version_id, prompt_version, model, explanation, created_at, updated_at) VALUES ('ae3282e8-37dd-55fd-a2fa-4e0eb60575a3', 'practice_batch_analysis.v1', 'deepseek-v4-flash', '句意为“离开房间的时候，请关窗”。动词“出る（でる）”表示“出去、离开”，与助词“を”搭配，“へやを出る”就是“离开房间”，故选 b。たつ＝站立；まつ＝等待；みる＝看。常见误区是把“出る”只理解为“出现”，但“を出る”可表示从场所离开；“～とき”前接动词辞书形，表示“做某事的时候”。', '2026-09-03 11:30:59.421043+08', '2026-09-03 11:30:59.421043+08') ON CONFLICT (question_version_id) DO NOTHING;
INSERT INTO public.question_ai_explanations (question_version_id, prompt_version, model, explanation, created_at, updated_at) VALUES ('b3afd0be-1511-49d6-89c7-67e07c9c6be0', 'practice_batch_analysis.v1', 'deepseek-v4-flash', '结论：选B“これ”。句子为“（ ）はうちの会社の新製品です”，“新製品”属于事物，需要能指代事物的指示代词“これ”。A“ここ”是地点代词，不能指产品；C“こんな”是连体词，后面必须接名词；D“この”也是连体词，须说成“この新製品は……”，不能直接放在“は”前。常见误区是把“これ”和“この”混淆，关键看空后是“は”还是名词。', '2026-09-03 14:37:50.530704+08', '2026-09-03 14:37:50.530704+08') ON CONFLICT (question_version_id) DO NOTHING;
INSERT INTO public.question_ai_explanations (question_version_id, prompt_version, model, explanation, created_at, updated_at) VALUES ('b56a6be9-5e82-43b3-8f02-c3453039a756', 'practice_batch_analysis.v1', 'deepseek-v4-flash', '题干“奥さんは( )仕事をしていますか”是问“你太太做什么样的工作”，需要修饰后面的名词「仕事」，表示“什么样的”，所以用「どんな」。“どこ”问地点；“どれ”用于从多个事物中选择，不能直接接「仕事」；“だれ”问人。「どんな＋名词」是最常用的询问性质、种类的搭配。句子也可理解为“她从事什么类型的工作”，因此本题应选「どんな」。', '2026-09-03 15:47:34.250068+08', '2026-09-03 15:47:34.250068+08') ON CONFLICT (question_version_id) DO NOTHING;
INSERT INTO public.question_ai_explanations (question_version_id, prompt_version, model, explanation, created_at, updated_at) VALUES ('c2ff1676-2992-46b4-8502-a23c8a136a95', 'practice_batch_analysis.v1', 'deepseek-v4-flash', '「万年筆」是细长形的书写工具，日语中细长物体用助数词「本」来数。如「一本、二本、三本」。「本」也可用于铅笔、伞、瓶子等细长物。注意「本」的读音会变化：三本读「さんぼん」。在这类量词搭配题中，看到笔类应首先想到「本」，不要写成「本」以外的量词。', '2026-09-03 15:47:34.250068+08', '2026-09-03 15:47:34.250068+08') ON CONFLICT (question_version_id) DO NOTHING;
INSERT INTO public.question_ai_explanations (question_version_id, prompt_version, model, explanation, created_at, updated_at) VALUES ('ca91f833-d884-471d-b76b-8a9fb4194c2d', 'practice_batch_analysis.v1', 'deepseek-v4-flash', '「りんご」是苹果，一般用助数词「個」来数，如「一個、二個」。此外也常用「一つ、二つ」的数法，但本题量词栏标准答案为「個」。「枚」用于薄平物品，“冊”用于书籍笔记本，“台”用于机械车辆，均不适合苹果。记住水果、蛋、球等立体小物体通常用「個」。', '2026-09-03 15:47:34.250068+08', '2026-09-03 15:47:34.250068+08') ON CONFLICT (question_version_id) DO NOTHING;
INSERT INTO public.question_ai_explanations (question_version_id, prompt_version, model, explanation, created_at, updated_at) VALUES ('caa208e9-d532-55bf-b956-67dc2d88316c', 'practice_batch_analysis.v1', 'deepseek-v4-flash', '答案应为D「そんな」。「( )難しい問題を出さないでください」中空格后是名词短语「難しい問題」，需要连体词修饰。D「そんな」作为连体词，意为“那样的”，可带不满或强调语气，“そんな難しい問題”＝“那么难的问题”，与「出さないでください」的请求/不满语气自然搭配。B「それ」不能修饰名词；C「そちら」多表地点方向；A「その」虽可接名词，但只表示“那个”，无法表达“那么难”的程度和抱怨语气。', '2026-09-03 11:33:43.277612+08', '2026-09-03 11:33:43.277612+08') ON CONFLICT (question_version_id) DO NOTHING;
INSERT INTO public.question_ai_explanations (question_version_id, prompt_version, model, explanation, created_at, updated_at) VALUES ('d5db3a2f-c2fe-56a7-88a8-10c8a5f809f3', 'practice_batch_analysis.v1', 'deepseek-v4-flash', '前半句说“以前这里不是银行”，后句说明过去实际情况“是电影院”，因此用名词过去肯定形式「でした」（C）。A「です」现在时与「昔」不符；B「ではない」现在否定；D「ではありませんでした」过去否定，均与“电影馆”这一肯定补充相反。', '2026-09-03 11:30:22.579731+08', '2026-09-03 11:30:22.579731+08') ON CONFLICT (question_version_id) DO NOTHING;
INSERT INTO public.question_ai_explanations (question_version_id, prompt_version, model, explanation, created_at, updated_at) VALUES ('df344fc9-4f84-514a-92b9-ef53dcd919b0', 'practice_batch_analysis.v1', 'deepseek-v4-flash', '“医者”的正确读音是“いしゃ”。其中“医”读“い”，“者”读“しゃ”。干扰项中“いじゃ”“きじゃ”不是正确拼读；“きしゃ”则是“汽車”或“記者”的读音。句意是“将来想成为医生”。误区在于“者”常出现在“若者（わかもの）”等训读词中，但在“医者”里是音读“しゃ”，不可浊化成“じゃ”。', '2026-09-03 11:30:59.421043+08', '2026-09-03 11:30:59.421043+08') ON CONFLICT (question_version_id) DO NOTHING;
INSERT INTO public.question_ai_explanations (question_version_id, prompt_version, model, explanation, created_at, updated_at) VALUES ('e050ae50-16de-5ba3-b8ff-d189b05e7da2', 'practice_batch_analysis.v1', 'deepseek-v4-flash', '对话中A向B确认“这里是公园入口吗”，B回答“是的”。确认时名词句用「ですか」（A）并带升调。B「です」是简单肯定，无确认语气；C「でしたか」为过去疑问；D「でした」为过去肯定，均不符合当前向对方确认的语境。', '2026-09-03 11:30:22.579731+08', '2026-09-03 11:30:22.579731+08') ON CONFLICT (question_version_id) DO NOTHING;
INSERT INTO public.question_ai_explanations (question_version_id, prompt_version, model, explanation, created_at, updated_at) VALUES ('e0e45853-6ec9-5b3e-8a18-a14fe2246a48', 'practice_batch_analysis.v1', 'deepseek-v4-flash', '答案应为D「この」。「( )会社はどんな会社ですか」中空格后已有名词「会社」，需要连体词修饰它。D「この」＋「会社」构成“这家公司”，“这家公司是什么样的公司”意思通顺。A「ここ」和B「これ」不能直接后续名词；C「こんな」也可接名词，但表示“这样的”，与后文「どんな会社ですか」（询问性质）不搭配：既然还在问“什么样的”，就不能先说“这样的”。', '2026-09-03 11:33:43.277612+08', '2026-09-03 11:33:43.277612+08') ON CONFLICT (question_version_id) DO NOTHING;
INSERT INTO public.question_ai_explanations (question_version_id, prompt_version, model, explanation, created_at, updated_at) VALUES ('e8163602-1e7b-5345-a1a1-7eced66df26b', 'practice_batch_analysis.v1', 'deepseek-v4-flash', '句中有“あまり”，后接否定，“あまり～ない”表示“不太……”。描述小说“しょうせつ”应有意思，常用“おもしろい”，其否定形式为“おもしろくない”，故选 a。其他词义：おいしくない＝不好吃；いそがしくない＝不忙；すずしくない＝不凉快。误区是只看到“ない”前应为“く”形，却忽略了句意中能与“小说”搭配的是“有趣”而非“好吃、忙、凉快”。', '2026-09-03 11:30:59.421043+08', '2026-09-03 11:30:59.421043+08') ON CONFLICT (question_version_id) DO NOTHING;
INSERT INTO public.question_ai_explanations (question_version_id, prompt_version, model, explanation, created_at, updated_at) VALUES ('e91ccb10-abc1-4651-b049-08dd686ff981', 'practice_batch_analysis.v1', 'deepseek-v4-flash', '结论：选A“どこ”。句子询问“那家有名的拉面店在哪儿”，谓语是“にありますか”，表示存在的场所，所以用地点疑问词“どこ”作补语。完整形式是“……ラーメン屋はどこにありますか”。B“どれ”用于从多个事物中选择一个；C“だれ”询问人；D“どんな”询问性质、种类，都不能回答地点。常见误区是把“どれ”和“どこ”混淆，关键看问题是“哪一个”还是“在哪里”。', '2026-09-03 14:37:50.530704+08', '2026-09-03 14:37:50.530704+08') ON CONFLICT (question_version_id) DO NOTHING;
INSERT INTO public.question_ai_explanations (question_version_id, prompt_version, model, explanation, created_at, updated_at) VALUES ('ea47817e-f5f2-56c7-a1d6-a94fbf3b77ad', 'practice_batch_analysis.v1', 'deepseek-v4-flash', '“映画”读作“えいが”，意为电影，故选 c。其中“映”读“えい”，“画”在这里读“が”，需要注意长音“えい”，以及浊音“が”，不能读成“えいか”。干扰项おうが、おうか、えいか都属于读音错误。常见误区是受中文“映画”字形影响读错，或把“画”单纯读作“か”。', '2026-09-03 11:30:59.421043+08', '2026-09-03 11:30:59.421043+08') ON CONFLICT (question_version_id) DO NOTHING;
INSERT INTO public.question_ai_explanations (question_version_id, prompt_version, model, explanation, created_at, updated_at) VALUES ('eda762d2-1094-4fc3-bb81-05ac5b15d5be', 'practice_batch_analysis.v1', 'deepseek-v4-flash', '题干是“彼の作品の中では、( )が一番好きですか”，意思是“在他的作品中，你最喜欢哪一个？”它是在三个以上的作品中选择其中一个，所以用疑问词「どれ」。“どこ”问地点；“だれ”问人；“どんな”用于询问性质、种类，不能表示从若干项中选择。常见句型「どれが一番好きですか」表示“哪个最喜欢”。本题易误选「どんな」，但它只能与名词连用或问“什么样的”，不用于“哪一个”的选择，因此正确答案是「どれ」。', '2026-09-03 15:47:34.250068+08', '2026-09-03 15:47:34.250068+08') ON CONFLICT (question_version_id) DO NOTHING;
INSERT INTO public.question_ai_explanations (question_version_id, prompt_version, model, explanation, created_at, updated_at) VALUES ('eea8f155-5f74-4998-a64f-3007fb0e5be1', 'practice_batch_analysis.v1', 'deepseek-v4-flash', '结论：选D“そんな”。空后是“難しい問題”，需要连体词修饰。“そんな難しい問題”意为“那样难的问题”，表达抱怨/不希望出现某种问题。A“その”虽然也可修饰名词，但表示特定的“那个问题”，而语境强调的是“这种/那样”的类型，并非特指某一个；B“それ”不能直接修饰名词；C“そちら”多指方向或对方处，与“問題”不搭配。本题关键是区分“その”的特指含义与“そんな”的“那样的、这种的”含义。', '2026-09-03 14:37:50.530704+08', '2026-09-03 14:37:50.530704+08') ON CONFLICT (question_version_id) DO NOTHING;
INSERT INTO public.question_ai_explanations (question_version_id, prompt_version, model, explanation, created_at, updated_at) VALUES ('f7273533-bd33-5901-b08e-d9a49b1a1f4a', 'practice_batch_analysis.v1', 'deepseek-v4-flash', '对话中B先回答“不，不是的”，随后说“那个（这台电脑）是李先生的”。指代前文提及的事物时用指示代词「それ」（C）。「その」是连体词，必须后接名词（如「そのパソコン」），不能单独使用；「こんな」「そんな」表示“这样/那样的”，不含指代前项这一台的意思。', '2026-09-03 11:30:22.579731+08', '2026-09-03 11:30:22.579731+08') ON CONFLICT (question_version_id) DO NOTHING;
INSERT INTO public.question_ai_explanations (question_version_id, prompt_version, model, explanation, created_at, updated_at) VALUES ('f8078373-32ce-5644-af45-54a4906b016b', 'practice_batch_analysis.v1', 'deepseek-v4-flash', '答案应为A「どこ」。「その前、田中さんが言った有名なラーメン屋は( )にありますか」中，「ある」表示存在，“有、在”，询问存在地点要用疑问词「どこ」。“…はどこにありますか”＝“……在哪里”。D「どんな」询问性质“什么样的”，与「にありますか」这一地点结构不搭配；B「どれ」用于从多个中选一个“哪个”；C「だれ」用来问人。因此只有A正确。', '2026-09-03 11:33:43.277612+08', '2026-09-03 11:33:43.277612+08') ON CONFLICT (question_version_id) DO NOTHING;
INSERT INTO public.question_ai_explanations (question_version_id, prompt_version, model, explanation, created_at, updated_at) VALUES ('f91d59c0-2917-5c40-a874-9c685e42ec72', 'practice_batch_analysis.v1', 'deepseek-v4-flash', '「りんご（苹果）」是球形、块状物，用「個」计数，如「りんご一個」。答案应写“個”。注意不要与水（杯）、花（本）等混淆。', '2026-09-03 11:30:22.579731+08', '2026-09-03 11:30:22.579731+08') ON CONFLICT (question_version_id) DO NOTHING;
INSERT INTO public.question_ai_explanations (question_version_id, prompt_version, model, explanation, created_at, updated_at) VALUES ('fca4cd1f-b78c-54a3-a4f7-5cb0b1aa8fae', 'practice_batch_analysis.v1', 'deepseek-v4-flash', '题干为“在水果中你最喜欢哪一种”。句中「果物の中で」给出范围，后接「が」和「一番好き」，需要一个能做主语的疑问代词，因此选「どれ」（B）。A「どの」是连体词，须修饰名词；C「どんな」表示“什么样的”，同样需修饰名词；D「だれ」问人，不用于水果。', '2026-09-03 11:30:22.579731+08', '2026-09-03 11:30:22.579731+08') ON CONFLICT (question_version_id) DO NOTHING;
INSERT INTO public.question_ai_explanations (question_version_id, prompt_version, model, explanation, created_at, updated_at) VALUES ('fdef0570-c112-597b-8779-ff3dd78591a8', 'practice_batch_analysis.v1', 'deepseek-v4-flash', '「猫（猫）」是小动物，用「匹」计数，如「猫一匹」。答案应写“匹”。小型动物一般用「匹」，大型动物用「頭」。', '2026-09-03 11:30:22.579731+08', '2026-09-03 11:30:22.579731+08') ON CONFLICT (question_version_id) DO NOTHING;
INSERT INTO public.question_ai_explanations (question_version_id, prompt_version, model, explanation, created_at, updated_at) VALUES ('fec75c65-1918-46e4-a838-4e3b81d2d516', 'practice_batch_analysis.v1', 'deepseek-v4-flash', '「ウサギ」是兔子。日语中鸟和兔子的量词都用「羽」，如「一羽、二羽」。一般小动物多用「匹」，但兔子习惯上用「羽」，这是特殊规则。常考例子还有「鶏（にわとり）」等鸟类也用「羽」。看到“兔子”不应想当然填「匹」，而要记住这一量词搭配，因此答案是「羽」。', '2026-09-03 15:47:34.250068+08', '2026-09-03 15:47:34.250068+08') ON CONFLICT (question_version_id) DO NOTHING;
